<script setup>
import{ref,onMounted}from'vue';
import{requestApi}from'../../shared/infrastructure/http/apiClient.js';
const props=defineProps({id:String}),certificate=ref(null),error=ref(''),busy=ref(false);
const labels={Issued:'Vigente · confirmado',Revoked:'Revocado',ReviewRequired:'Requiere nueva revisión',UnableToVerify:'No se pudo confirmar la vigencia',PendingReview:'Pendiente de revisión',Rejected:'Solicitud rechazada'};
async function load(){busy.value=true;error.value='';try{certificate.value=await requestApi(`/api/v1/public/certificates/${props.id}`);}catch(e){certificate.value=null;error.value=e.status===404?'No hay información suficiente para este código. No se confirma su origen.':'UnableToVerify · No se pudo confirmar la vigencia. Inténtalo nuevamente.';}finally{busy.value=false;}}
onMounted(load);
</script>
<template><main class="workspace public-verification"><header class="topbar"><div><p class="eyebrow">CONSULTA PÚBLICA</p><h1>EventOre</h1></div><a href="/">Acceso de organizaciones</a></header><section class="panel"><h2>Verificación de trazabilidad</h2><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="busy" role="status">Consultando estado vigente…</p><template v-if="certificate"><h3>{{certificate.product.name}}</h3><p :class="['alert',certificate.status==='Issued'?'':'error']" role="status">{{labels[certificate.status]??certificate.status}}</p><p class="identifier">{{certificate.certificateId}}</p><p>{{certificate.scope}}</p><p v-if="certificate.issuer">Emisor: {{certificate.issuer}}</p><p>Consulta: {{new Date(certificate.checkedAt).toLocaleString('es-PE')}}</p><p>Última publicación: {{new Date(certificate.updatedAt).toLocaleString('es-PE')}}</p><p v-if="certificate.status!=='Issued'" class="muted">No se presenta el origen como confirmado. La emisión impresa no garantiza vigencia futura.</p><h3>Materiales publicados</h3><ul><li v-for="(material,index) in certificate.materials" :key="index">{{material.mineralType}} · {{material.quantityGrams}} g · {{material.evidenceLevel==='Verified'?'Evidencia verificada':material.evidenceLevel==='External'?'Material externo declarado':'Información declarada'}}</li></ul><h3>Hitos publicados</h3><ol><li v-for="(event,index) in certificate.milestones" :key="index">{{event.type}} · {{new Date(event.at).toLocaleString('es-PE')}}</li></ol><p class="muted">El QR identifica un registro y permite consultar su estado. No prueba por sí mismo la autenticidad física de la joya.</p></template><button :disabled="busy" @click="load">Actualizar vigencia</button></section></main></template>
